"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { DateTime } from "luxon";
import { signIn, useSession } from "@/lib/auth/client";
import { ticketQrDataUrl } from "@/lib/marine/qr";
import { AdminPanels } from "@/components/marine/admin-panels";
import type { MarineRole, MarineTripSummary, MarineTripView, CrewPassenger, AdminPassenger } from "@/lib/marine/types";

type ApiState = { role: MarineRole; organizationId: string; trips: MarineTripSummary[]; trip: MarineTripView | null };
const inputClass = "min-h-12 w-full rounded-xl border border-slate-300 bg-white px-4 text-base text-slate-900";
const buttonClass = "min-h-12 rounded-xl bg-sky-800 px-5 py-3 text-base font-semibold text-white disabled:opacity-50";
const secondaryClass = "min-h-12 rounded-xl border border-slate-400 bg-white px-4 py-3 text-base font-semibold text-slate-900";
const panelClass = "rounded-2xl border border-slate-200 bg-white p-4 shadow-sm";
function errorText(value: unknown) { if (value instanceof TypeError) return "Se perdió la conexión. La operación no se confirmó; revisa la lista maestra y reintenta la misma operación."; if (value instanceof SyntaxError) return "No pudimos leer la respuesta. Reintenta la misma operación."; return value instanceof Error ? value.message : "No se pudo completar. Revisa la conexión e inténtalo de nuevo."; }
function localDate(value: string) { return new Intl.DateTimeFormat("es-VE", { dateStyle: "medium", timeStyle: "short", timeZone: "America/Caracas" }).format(new Date(value)); }
export function marineLocalTimeToUtc(value: string) {
  const date = DateTime.fromISO(value, { zone: "America/Caracas" });
  if (!date.isValid) throw new Error("Revisa la fecha y la hora del paseo.");
  return date.toUTC().toISO()!;
}
function formatMoney(minor: number, currency: "USD" | "VES") { return new Intl.NumberFormat("es-VE", { style: "currency", currency, minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(minor / 100); }
export function amountToMinor(value: string) { if (!value.trim()) return 0; const match = /^(\d{1,8})(?:[.,](\d{1,2}))?$/.exec(value.trim()); if (!match) throw new Error("Escribe un monto con hasta dos decimales, por ejemplo 25,50."); return Number(match[1]) * 100 + Number((match[2] || "").padEnd(2, "0")); }
function freshId() { return crypto.randomUUID(); }
export function canBeginMarineCommand(inFlight: boolean, pending: boolean) { return !inFlight && !pending; }
export function shouldFlagOfflineReview(markerExists: boolean, online: boolean, status: string | undefined, commandPending: boolean) { return markerExists && online && ["boarding", "underway"].includes(status || "") && !commandPending; }
export async function submitMarineDraft(send: () => Promise<boolean>, clear: () => void) { const saved = await send(); if (saved) clear(); return saved; }

export function MarineApp() {
  const { data: session, isPending } = useSession();
  const [data, setData] = useState<ApiState | null>(null);
  const [selectedId, setSelectedId] = useState("");
  const [tab, setTab] = useState("Hoy");
  const [adminView, setAdminView] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [connected, setConnected] = useState(true);
  const [detailLoading, setDetailLoading] = useState(true);
  const [code, setCode] = useState("");
  const [personQuery, setPersonQuery] = useState("");
  const [selectedPerson, setSelectedPerson] = useState<CrewPassenger | AdminPassenger | null>(null);
  const [scanOpen, setScanOpen] = useState(false);
  const [offlineMarker, setOfflineMarker] = useState("");
  const [flaggingOffline, setFlaggingOffline] = useState(false);
  const offlineFlagInFlight = useRef(false);
  const offlineFlagRequestId = useRef<string | null>(null);
  const requestController = useRef<AbortController | null>(null);
  const refreshVersion = useRef(0);
  const mutationInFlight = useRef(false);
  const pendingMutation = useRef<{ action: string; body: Record<string, unknown> } | null>(null);
  const [canRetry, setCanRetry] = useState(false);
  const trip = data?.trip;
  const isAdmin = data?.role === "owner" || data?.role === "admin";
  useEffect(() => { if (data?.role) { setAdminView(isAdmin); setTab(isAdmin ? "Resumen" : "Hoy"); } }, [data?.role, isAdmin]);
  const operationsDisabled = busy || Boolean(pendingMutation.current) || flaggingOffline || !connected || Boolean(offlineMarker) || Boolean(trip?.reconciliationRequired) || !trip || ["completed", "cancelled"].includes(trip.status);
  const refresh = useCallback(async (tripId?: string) => {
    if (!session) return;
    const version = ++refreshVersion.current;
    requestController.current?.abort();
    const controller = new AbortController();
    requestController.current = controller;
    setDetailLoading(true);
    try {
      const url = new URL("/api/marine", window.location.origin);
      if (tripId) url.searchParams.set("tripId", tripId);
      const response = await fetch(url, { cache: "no-store", signal: controller.signal });
      const body = await response.json();
      if (version !== refreshVersion.current) return;
      if (!response.ok) throw new Error(body.message || body.error?.message || "No se pudo cargar la información.");
      setData(body as ApiState); setSelectedId(tripId || body.trip?.id || body.trips?.[0]?.id || ""); setConnected(true); setError(""); setDetailLoading(false);
    } catch (e) { if (e instanceof DOMException && e.name === "AbortError") return; if (version === refreshVersion.current) { setConnected(false); setError(errorText(e)); setDetailLoading(false); } }
  }, [session]);
  useEffect(() => { void refresh(selectedId || undefined); }, [refresh, selectedId]);
  useEffect(() => { if (!data?.organizationId || !selectedId) return; const key = `marine-offline:${data.organizationId}:${selectedId}`; setOfflineMarker(localStorage.getItem(key) || ""); }, [data?.organizationId, selectedId]);
  useEffect(() => { const online = () => { setConnected(true); void refresh(selectedId || undefined); }; const offline = () => { setConnected(false); if (data?.organizationId && selectedId && ["boarding", "underway"].includes(data.trip?.status || "")) { const value = `Sin conexión durante el paseo · ${new Date().toISOString()}`; localStorage.setItem(`marine-offline:${data.organizationId}:${selectedId}`, value); setOfflineMarker(value); } }; window.addEventListener("online", online); window.addEventListener("offline", offline); return () => { window.removeEventListener("online", online); window.removeEventListener("offline", offline); }; }, [refresh, selectedId, data?.organizationId, data?.trip?.status]);
  const flagOfflineReview = useCallback(async () => {
    const orgId = data?.organizationId;
    if (!orgId || !selectedId || !navigator.onLine || !["boarding", "underway"].includes(data.trip?.status || "") || offlineFlagInFlight.current || mutationInFlight.current || pendingMutation.current) return;
    const key = `marine-offline:${orgId}:${selectedId}`;
    if (!localStorage.getItem(key)) return;
    offlineFlagInFlight.current = true; setFlaggingOffline(true);
    offlineFlagRequestId.current ||= freshId();
    try {
      const response = await fetch("/api/marine", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "flagReconciliation", tripId: selectedId, requestId: offlineFlagRequestId.current, note: "Período sin conexión registrado. Comparar la lista maestra impresa antes de continuar." }) });
      const body = await response.json();
      if (!response.ok) throw new Error(body.message || body.error?.message || "No se pudo registrar la revisión.");
      if (body.trip?.reconciliationRequired) {
        localStorage.removeItem(key); setOfflineMarker(""); setData((prev) => prev ? { ...prev, trip: body.trip } : prev); offlineFlagRequestId.current = null;
      }
      await refresh(selectedId);
    } catch (e) { setError(errorText(e)); }
    finally { offlineFlagInFlight.current = false; setFlaggingOffline(false); }
  }, [data?.organizationId, data?.trip?.status, selectedId, refresh]);
  useEffect(() => { const key = data?.organizationId && selectedId ? `marine-offline:${data.organizationId}:${selectedId}` : ""; const markerExists = key ? Boolean(localStorage.getItem(key)) : false; if (markerExists && (trip?.reconciliationRequired || trip?.status === "planned" || trip?.status === "completed" || trip?.status === "cancelled")) { localStorage.removeItem(key); setOfflineMarker(""); return; } const pending = offlineFlagInFlight.current || mutationInFlight.current || Boolean(pendingMutation.current); if (!shouldFlagOfflineReview(markerExists, connected && navigator.onLine, trip?.status, pending)) return; void flagOfflineReview(); }, [busy, connected, data?.organizationId, selectedId, offlineMarker, trip?.status, trip?.reconciliationRequired, flagOfflineReview]);
  async function sendMutation(action: string, body: Record<string, unknown>): Promise<boolean> {
    if (mutationInFlight.current) return false;
    mutationInFlight.current = true;
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/marine", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const result = await response.json();
      if (!response.ok) { pendingMutation.current = null; setCanRetry(false); throw new Error(result.message || result.error?.message || "No se pudo guardar. Inténtalo de nuevo."); }
      pendingMutation.current = null; setCanRetry(false);
      if (action === "lookupTicket" && result.passenger) { setSelectedPerson(result.passenger); setTab("Pasajeros"); setCode(""); return true; }
      if (["flagReconciliation", "resolveReconciliation"].includes(action) && data?.organizationId) { localStorage.removeItem(`marine-offline:${data.organizationId}:${selectedId}`); setOfflineMarker(""); }
      if (action !== "exportManifest") { const nextId = action === "createTrip" ? result.trip.id : selectedId; setSelectedId(nextId); setData((prev) => prev ? { ...prev, trip: result.trip } : prev); await refresh(nextId); }
      else { const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([result.content], { type: "text/csv;charset=utf-8" })); link.download = result.filename || "manifiesto.csv"; link.click(); URL.revokeObjectURL(link.href); }
      return true;
    } catch (e) { if (e instanceof TypeError || e instanceof SyntaxError) { if (data?.organizationId && selectedId && ["boarding", "underway"].includes(data.trip?.status || "")) { const value = `No se pudo confirmar la conexión · ${new Date().toISOString()}`; localStorage.setItem(`marine-offline:${data.organizationId}:${selectedId}`, value); setOfflineMarker(value); setConnected(false); } setCanRetry(true); } setError(errorText(e)); return false; } finally { mutationInFlight.current = false; setBusy(false); }
  }
  async function command(action: string, fields: Record<string, unknown> = {}, confirmation?: string): Promise<boolean> {
    if (!canBeginMarineCommand(mutationInFlight.current, Boolean(pendingMutation.current))) { setError("Hay una operación sin confirmar. Reintenta esa misma operación antes de iniciar otra."); return false; }
    if (!connected && !(action === "flagReconciliation" && navigator.onLine)) { setError("Sin conexión. La lista impresa es solo de consulta; anota los cambios en la lista maestra."); return false; }
    if ((offlineMarker || trip?.reconciliationRequired) && !["flagReconciliation", "correctMovement", "resolveReconciliation", "exportManifest"].includes(action)) { setError("Este paseo requiere una revisión de la lista maestra antes de continuar."); return false; }
    if (confirmation && !window.confirm(confirmation)) return false;
    const body = { action, ...(action === "createTrip" ? {} : { tripId: selectedId }), requestId: freshId(), ...fields };
    pendingMutation.current = { action, body };
    return await sendMutation(action, body);
  }
  async function retryMutation() {
    const pending = pendingMutation.current;
    if (pending && canRetry) await sendMutation(pending.action, pending.body);
  }
  function selectTrip(id: string) {
    setSelectedPerson(null); setCode(""); setData((prev) => prev ? { ...prev, trip: null } : prev); setDetailLoading(true);
    if (id === selectedId) void refresh(id || undefined);
    else setSelectedId(id);
  }
  if (isPending) return <main className="p-6">Cargando…</main>;
  if (!session) return <MarineLogin />;
  const people = (trip?.passengers ?? []) as (CrewPassenger | AdminPassenger)[];
  const filteredPeople = people.filter((p) => `${p.name} ${p.documentMasked}`.toLocaleLowerCase("es").includes(personQuery.toLocaleLowerCase("es")));
  return <main className="min-h-screen bg-slate-50 pb-24 text-slate-950"><style jsx global>{`@page{margin:14mm}@media print{body *{visibility:hidden!important}.marine-print-scope,.marine-print-scope *{visibility:visible!important}.marine-print-scope{position:absolute!important;inset:0!important;width:100%!important;margin:0!important;border:0!important;box-shadow:none!important}.marine-print-scope li{break-inside:avoid;border-bottom:1px solid #cbd5e1;padding:8px 0}.marine-print-scope button,.marine-print-scope input,.marine-no-print{display:none!important}}`}</style>
    <header className="sticky top-0 z-10 border-b bg-white px-4 py-3"><div className="mx-auto flex max-w-3xl items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wide text-sky-800">La Bambola · Morrocoy</p><h1 className="text-xl font-bold">{isAdmin && adminView ? "Panel de administración" : "Operaciones"}</h1>{data && <p className="text-sm font-semibold">Rol: {isAdmin ? "Administración" : "Tripulación"}</p>}</div><span className={`rounded-full px-3 py-2 text-sm font-semibold ${connected ? "bg-emerald-100 text-emerald-900" : "bg-amber-100 text-amber-950"}`}>{connected ? "Con conexión" : "Sin conexión · solo lectura"}</span></div></header>
    <div className="mx-auto max-w-3xl space-y-4 p-4">
      {error && <div role="alert" className="rounded-xl bg-red-50 p-4 text-base text-red-900">{error}{canRetry && pendingMutation.current && <button className={`${buttonClass} ml-2`} onClick={() => void retryMutation()}>Reintentar misma operación</button>}<button className="ml-3 underline" onClick={() => setError("")}>Cerrar</button></div>}
      <label className="block text-sm font-semibold">Paseo seleccionado<select className={`${inputClass} mt-1`} value={selectedId} disabled={busy || flaggingOffline || Boolean(pendingMutation.current)} onChange={(e) => selectTrip(e.target.value)}><option value="">Selecciona un paseo</option>{data?.trips.map((t) => <option key={t.id} value={t.id}>{localDate(t.startAt)} · {t.title}</option>)}</select></label>
      {isAdmin && !adminView && <div className={`${panelClass} border-sky-200 bg-sky-50`}><div className="flex flex-wrap items-center justify-between gap-2"><strong>Vista de operaciones administrativas · acceso completo</strong><button className={secondaryClass} disabled={busy || flaggingOffline || Boolean(pendingMutation.current)} onClick={() => setAdminView(true)}>Volver a paneles</button></div></div>}
      {!trip && <div className={panelClass}><h2 className="text-lg font-bold">{detailLoading ? "Cargando paseo…" : isAdmin ? "Crear un paseo" : "Todavía no hay paseos asignados"}</h2>{!detailLoading && isAdmin && <CreateTrip onCreate={(fields) => void command("createTrip", fields)} busy={busy} />}</div>}
      {trip && offlineMarker && <section role="alert" className="rounded-xl border border-amber-400 bg-amber-50 p-4"><strong>Revisión pendiente</strong><p>Se perdió la conexión durante el paseo. Revisa la lista maestra impresa antes de registrar más movimientos.</p>{canRetry && pendingMutation.current && <button className={`${buttonClass} mt-3`} onClick={() => void retryMutation()}>Reintentar misma operación</button>}{!trip.reconciliationRequired && <button className={`${buttonClass} mt-3`} disabled={!connected || busy || flaggingOffline || Boolean(pendingMutation.current)} onClick={() => void flagOfflineReview()}>{flaggingOffline ? "Registrando revisión…" : "Reintentar revisión"}</button>}</section>}
      {trip?.reconciliationRequired && <section role="status" className="rounded-xl border border-amber-400 bg-amber-50 p-4"><strong>Revisión pendiente con Rosanni</strong><p>Compara la lista maestra impresa con los movimientos del sistema. Las operaciones se reanudarán al confirmar la revisión.</p>{isAdmin && <button className={`${secondaryClass} mt-2`} disabled={busy || flaggingOffline || Boolean(pendingMutation.current)} onClick={() => { setAdminView(false); setTab("Administración"); }}>Abrir revisión</button>}</section>}
      {isAdmin && adminView && <AdminPanels trips={data?.trips || []} navigationDisabled={busy || flaggingOffline || Boolean(pendingMutation.current)} onOpenTrip={(id) => { if (busy || flaggingOffline || pendingMutation.current) return; selectTrip(id); setAdminView(false); setTab("Hoy"); }} onOperations={() => { if (!busy && !flaggingOffline && !pendingMutation.current) { setAdminView(false); setTab("Hoy"); } }} onAdministration={() => { if (!busy && !flaggingOffline && !pendingMutation.current) { setAdminView(false); setTab("Administración"); } }} />}
      {trip && tab === "Administración" && isAdmin && !adminView && <AdminPanel trip={trip} busy={busy || Boolean(pendingMutation.current)} command={command} />}
      {trip && !adminView && tab !== "Administración" && <>
        {tab === "Hoy" && <section className={`${panelClass} space-y-3`}><div className="flex items-start justify-between gap-3"><div><h2 className="text-lg font-bold">{trip.title}</h2><p className="text-slate-600">{localDate(trip.startAt)} · {trip.status === "planned" ? "Planificado" : trip.status === "boarding" ? "Abordando" : trip.status === "underway" ? "En paseo" : trip.status === "completed" ? "Finalizado" : "Cancelado"}</p></div><span className="rounded-full bg-sky-100 px-3 py-2 font-bold">A bordo {trip.totals.aboard}</span></div>
          <div className="grid grid-cols-2 gap-2 text-center sm:grid-cols-4"><Metric label="Registrados" value={trip.totals.registered} /><Metric label="A bordo" value={trip.totals.aboard} /><Metric label="En parada" value={trip.totals.away} /><Metric label="Desembarcados" value={trip.totals.deboarded} /></div>
          <button className={`${buttonClass} w-full`} onClick={() => setScanOpen(true)} disabled={busy || !connected || trip.status === "completed" || trip.status === "cancelled"}>Escanear boleto</button>
          <label className="block font-semibold">Código del boleto<input className={`${inputClass} mt-1`} value={code} onChange={(e) => setCode(e.target.value.toUpperCase())} placeholder="Pega o escribe el código" autoCapitalize="characters" /></label><button className={`${secondaryClass} w-full`} disabled={!code.trim() || !connected || busy} onClick={() => lookupTicket(code)}>Buscar boleto</button>
        </section>}
        {(tab === "Hoy" || tab === "Pasajeros") && <section className={`${panelClass} marine-print-scope`}><div className="mb-3 flex items-center justify-between gap-2"><h2 className="text-lg font-bold">Pasajeros</h2><button className={`${secondaryClass} marine-no-print`} onClick={() => window.print()}>Imprimir lista de equipo</button></div><input className={inputClass} value={personQuery} onChange={(e) => setPersonQuery(e.target.value)} placeholder="Buscar por nombre" aria-label="Buscar pasajero por nombre" />{selectedPerson && <div className="marine-no-print"><MovementConfirm person={selectedPerson} onClose={() => setSelectedPerson(null)} onConfirm={(movement) => { void command("movePassenger", { passengerId: selectedPerson.id, movement }); setSelectedPerson(null); }} /></div>}
          <ul className="mt-3 space-y-2">{filteredPeople.map((p) => <li key={p.id} className="flex items-center justify-between gap-2 rounded-xl border p-3"><div className="min-w-0"><p className="truncate font-semibold">{p.name}</p><p className="text-sm text-slate-600">{p.documentMasked || (p.registered ? "Registrado" : "Pendiente de registro")} · {movementLabel(p.movement)}</p></div><button className={secondaryClass} onClick={() => setSelectedPerson(p)} disabled={!connected || busy || !p.registered}>Elegir</button></li>)}</ul>{filteredPeople.length === 0 && <p className="py-4 text-slate-600">No encontramos pasajeros con ese nombre.</p>}
        </section>}
        {(tab === "Hoy" || tab === "Servicios") && <section className={panelClass}><h2 className="text-lg font-bold">Servicios</h2><p className="mb-3 text-sm text-slate-600">Marca una sola vez cuando termines una tarea.</p>{trip.services.filter((s) => s.status !== "cancelled").map((s) => <div key={s.id} className="flex items-center justify-between gap-2 border-t py-3"><div><p className="font-semibold">{s.label} × {s.quantity}</p><p className="text-sm text-slate-600">{s.status === "done" ? "Listo" : s.status === "doing" ? "En curso" : "Pendiente"}</p></div>{s.status !== "done" && <button className={buttonClass} disabled={operationsDisabled} onClick={() => void command("changeServiceStatus", { serviceId: s.id, status: s.status === "pending" ? "doing" : "done" })}>{s.status === "pending" ? "Empezar" : "Listo"}</button>}</div>)}<ServiceRequest disabled={operationsDisabled} onSubmit={(label, quantity) => command("addServiceRequest", { label, quantity })} /></section>}
        {tab === "Hoy" && <><IncidentForm disabled={operationsDisabled} command={command} /><section className={panelClass}><h2 className="text-lg font-bold">Notas del paseo</h2>{trip.incidents.length ? <ul className="mt-2 space-y-2">{trip.incidents.slice().reverse().map((incident) => <li key={incident.id} className="rounded-lg bg-slate-100 p-3"><p>{incident.text}</p><time className="text-sm text-slate-600">{localDate(incident.createdAt)}</time></li>)}</ul> : <p className="mt-2 text-slate-600">Todavía no hay notas.</p>}</section></>}
      </>}
    </div>
    {trip && !adminView && tab !== "Administración" && <nav className="fixed inset-x-0 bottom-0 z-20 grid grid-cols-3 border-t bg-white p-2">{["Hoy", "Pasajeros", "Servicios"].map((name) => <button key={name} className={`min-h-12 rounded-xl font-semibold ${tab === name ? "bg-sky-100 text-sky-950" : "text-slate-700"}`} onClick={() => setTab(name)}>{name}</button>)}</nav>}
    {scanOpen && <Scanner onClose={() => setScanOpen(false)} onCode={(value) => { setScanOpen(false); void lookupTicket(value); }} />}
  </main>;
  async function lookupTicket(value: string) {
    const pass = people.find((p) => ("ticketCode" in p ? p.ticketCode?.toUpperCase() === value.trim().toUpperCase() : false));
    if (pass) { setSelectedPerson(pass); setCode(""); return; }
    if (!value.trim()) return;
    await command("lookupTicket", { ticketCode: value.trim().toUpperCase() });
  }
}

function MarineLogin() {
  const router = useRouter(); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  return <main className="grid min-h-screen place-items-center bg-slate-50 p-4"><form className={`${panelClass} w-full max-w-sm space-y-4`} onSubmit={async (e) => { e.preventDefault(); setBusy(true); const { error: err } = await signIn.email({ email, password }); setBusy(false); if (err) setError("No pudimos iniciar sesión. Revisa el correo y la contraseña."); else { router.push("/nautica"); router.refresh(); } }}><p className="text-sm font-bold uppercase text-sky-800">La Bambola · Morrocoy</p><h1 className="text-2xl font-bold">Entrar a operaciones</h1><label className="block font-semibold">Correo<input className={`${inputClass} mt-1`} type="email" autoComplete="username" required value={email} onChange={(e) => setEmail(e.target.value)} /></label><label className="block font-semibold">Contraseña<input className={`${inputClass} mt-1`} type="password" autoComplete="current-password" required value={password} onChange={(e) => setPassword(e.target.value)} /></label>{error && <p role="alert" className="text-red-800">{error}</p>}<button className={`${buttonClass} w-full`} disabled={busy}>{busy ? "Entrando…" : "Entrar"}</button></form></main>;
}
function Metric({ label, value }: { label: string; value: number }) { return <div className="rounded-xl bg-slate-100 p-3"><div className="text-2xl font-bold">{value}</div><div className="text-sm text-slate-700">{label}</div></div>; }
function movementLabel(value: string) { return ({ awaiting: "Por abordar", aboard: "A bordo", away: "En parada", deboarded: "Desembarcó" } as Record<string, string>)[value] || value; }
function MovementConfirm({ person, onClose, onConfirm }: { person: CrewPassenger | AdminPassenger; onClose: () => void; onConfirm: (movement: "board" | "offboard" | "return" | "deboard") => void }) {
  const next: Record<string, { movement: "board" | "offboard" | "return" | "deboard"; label: string }[]> = { awaiting: [{ movement: "board", label: "Confirmar abordaje" }], aboard: [{ movement: "offboard", label: "Bajó en una parada" }, { movement: "deboard", label: "Desembarcó al final" }], away: [{ movement: "return", label: "Regresó al barco" }], deboarded: [] };
  return <div className="my-3 rounded-xl border-2 border-sky-700 bg-sky-50 p-4"><p className="text-lg font-bold">{person.name}</p><p>Documento: {person.documentMasked || "No indicado"}</p><p className="mb-3">Estado: {movementLabel(person.movement)}</p><div className="flex flex-wrap gap-2">{(next[person.movement] || []).map((item) => <button key={item.movement} className={buttonClass} onClick={() => onConfirm(item.movement)}>{item.label}</button>)}<button className={secondaryClass} onClick={onClose}>Volver</button></div></div>;
}
function CreateTrip({ onCreate, busy }: { onCreate: (fields: Record<string, unknown>) => void; busy: boolean }) {
  const [title, setTitle] = useState("Paseo en lancha"); const [startAt, setStart] = useState(""); const [endAt, setEnd] = useState(""); const [mode, setMode] = useState("public"); const [capacity, setCapacity] = useState("130");
  return <form className="mt-3 space-y-3" onSubmit={(e) => { e.preventDefault(); onCreate({ title, startAt: marineLocalTimeToUtc(startAt), endAt: marineLocalTimeToUtc(endAt), mode, capacity: Number(capacity) }); }}><label className="block">Nombre<input className={inputClass} required minLength={2} maxLength={120} value={title} onChange={(e) => setTitle(e.target.value)} /></label><div className="grid gap-3 sm:grid-cols-2"><label>Inicio (hora de Venezuela)<input className={inputClass} type="datetime-local" required value={startAt} onChange={(e) => setStart(e.target.value)} /></label><label>Fin (hora de Venezuela)<input className={inputClass} type="datetime-local" required value={endAt} onChange={(e) => setEnd(e.target.value)} /></label></div><label className="block">Tipo<select className={inputClass} value={mode} onChange={(e) => setMode(e.target.value)}><option value="public">Público</option><option value="private">Privado</option></select></label><label className="block">Capacidad<input className={inputClass} type="number" min="1" max="130" required value={capacity} onChange={(e) => setCapacity(e.target.value)} /></label><button className={buttonClass} disabled={busy}>Crear paseo</button></form>;
}
function ServiceRequest({ disabled, onSubmit }: { disabled: boolean; onSubmit: (label: string, quantity: number) => Promise<boolean> }) { const [label, setLabel] = useState(""); const [quantity, setQuantity] = useState("1"); return <form className="mt-4 space-y-2 border-t pt-4" onSubmit={async (e) => { e.preventDefault(); if (disabled) return; await submitMarineDraft(() => onSubmit(label.trim(), Number(quantity)), () => { setLabel(""); setQuantity("1"); }); }}><h3 className="font-bold">Pedir un servicio</h3><fieldset disabled={disabled} className="space-y-2"><label className="block">Qué necesitas<input className={inputClass} placeholder="Ej. agua, chaleco" value={label} onChange={(e) => setLabel(e.target.value)} minLength={2} maxLength={160} required /></label><div className="flex gap-2"><label className="block flex-1">Cantidad<input className={inputClass} type="number" min="1" max="130" value={quantity} onChange={(e) => setQuantity(e.target.value)} /></label><button className={buttonClass}>Añadir</button></div></fieldset></form>; }
function AdminPanel({ trip, busy, command }: { trip: MarineTripView; busy: boolean; command: (action: string, fields?: Record<string, unknown>, confirmation?: string) => Promise<boolean> }) {
  const [selectedTicket, setSelectedTicket] = useState("");
  const [physicalCount, setPhysicalCount] = useState("");
  const [countConfirmed, setCountConfirmed] = useState(false);
  const [cancellationReason, setCancellationReason] = useState("");
  useEffect(() => { setPhysicalCount(""); setCountConfirmed(false); }, [trip.status]);
  const [booking, setBooking] = useState({ reference: "", customerName: "", customerPhone: "", seats: "1", status: "confirmed", agency: "", totalAmount: "0", currency: "USD" }); const [payment, setPayment] = useState({ bookingId: "", amount: "", currency: "USD", method: "Efectivo", reference: "" }); const [cost, setCost] = useState({ label: "", amount: "", currency: "USD" }); const [service, setService] = useState({ label: "", quantity: "1", unitAmount: "0", currency: "USD" });
  const adminPeople = trip.passengers as AdminPassenger[];
  return <div className="space-y-4"><section className={panelClass}><h2 className="text-xl font-bold">Administración</h2><p className="text-slate-600">Reservas, cobros, enlaces y cierre de paseo.</p><button className={`${secondaryClass} mt-3 w-full`} disabled={busy} onClick={() => void command("exportManifest", {}, "El manifiesto incluye datos personales. ¿Descargarlo en este dispositivo autorizado?")}>Descargar manifiesto completo (CSV)</button><p className="mt-2 text-sm text-slate-600">El archivo incluye datos personales. Guárdalo solo en un dispositivo autorizado.</p></section><details className={panelClass}><summary className="cursor-pointer text-lg font-bold">Crear otro paseo</summary><CreateTrip onCreate={(fields) => void command("createTrip", fields)} busy={busy} /></details>
    <section className={`${panelClass} space-y-3`}><h3 className="text-lg font-bold">Crear una reserva</h3><form className="space-y-2" onSubmit={(e) => { e.preventDefault(); void command("createBooking", { reference: booking.reference, customerName: booking.customerName, customerPhone: booking.customerPhone, seats: Number(booking.seats), status: booking.status, agency: booking.agency, totalMinor: amountToMinor(booking.totalAmount), currency: booking.currency }).then((saved) => { if (saved) setBooking({ ...booking, reference: "", customerName: "", customerPhone: "", agency: "", totalAmount: "0" }); }); }}><label className="block">Referencia<input className={inputClass} required value={booking.reference} onChange={(e) => setBooking({ ...booking, reference: e.target.value })} /></label><label className="block">Nombre del responsable<input className={inputClass} required value={booking.customerName} onChange={(e) => setBooking({ ...booking, customerName: e.target.value })} /></label><label className="block">Teléfono<input className={inputClass} type="tel" required value={booking.customerPhone} onChange={(e) => setBooking({ ...booking, customerPhone: e.target.value })} /></label><div className="grid grid-cols-2 gap-2"><label>Lugares<input className={inputClass} type="number" min="1" max="130" value={booking.seats} onChange={(e) => setBooking({ ...booking, seats: e.target.value })} /></label><label>Estado<select className={inputClass} value={booking.status} onChange={(e) => setBooking({ ...booking, status: e.target.value })}><option value="confirmed">Confirmada</option><option value="waitlist">Lista de espera</option></select></label></div><label className="block">Agencia o referencia<input className={inputClass} value={booking.agency} onChange={(e) => setBooking({ ...booking, agency: e.target.value })} /></label><div className="grid grid-cols-2 gap-2"><label>Total acordado ({booking.currency})<input className={inputClass} type="text" inputMode="decimal" pattern="[0-9]{1,8}([.,][0-9]{1,2})?" placeholder="Ej. 25,50" value={booking.totalAmount} onChange={(e) => setBooking({ ...booking, totalAmount: e.target.value })} /></label><label>Moneda<select className={inputClass} value={booking.currency} onChange={(e) => setBooking({ ...booking, currency: e.target.value })}><option>USD</option><option>VES</option></select></label></div><button className={buttonClass} disabled={busy}>Guardar reserva</button></form></section>
    <section className={panelClass}><h3 className="text-lg font-bold">Pasajeros y enlaces de registro</h3><p className="text-sm text-slate-600">Cada lugar tiene su propio enlace. No compartas datos entre pasajeros.</p><ul className="mt-2 divide-y">{adminPeople.map((p) => <li key={p.id} className="py-3"><p className="font-semibold">{p.name || `Registro pendiente · ${trip.bookings.find((b) => b.id === p.bookingId)?.reference || "reserva"}` } · {p.documentMasked || "Documento pendiente"}</p><div className="mt-2 flex flex-wrap gap-2">{p.registrationLink && <button className={secondaryClass} onClick={() => void navigator.clipboard.writeText(new URL(p.registrationLink || "", window.location.origin).toString())}>Copiar enlace</button>}{p.ticketCode && <button className={secondaryClass} onClick={() => { setSelectedTicket(p.ticketCode!); }}>Ver boleto e imprimir</button>}<button className={secondaryClass} disabled={busy} onClick={() => void command("rotateRegistration", { passengerId: p.id }, "Crear un enlace nuevo y revocar el anterior?")}>Renovar enlace</button>{p.registered && <PassengerCorrection person={p} revision={trip.revision} busy={busy} command={command} />}{p.movement !== "awaiting" && <MovementCorrection person={p} revision={trip.revision} busy={busy} command={command} />}</div></li>)}</ul></section>
    <section className={panelClass}><h3 className="text-lg font-bold">Reservas</h3><ul className="divide-y">{trip.bookings.map((b) => <li key={b.id} className="flex flex-wrap items-center justify-between gap-2 py-3"><span>{b.reference} · {b.customerName} · {b.seats} lugares · {b.status === "confirmed" ? "Confirmada" : b.status === "waitlist" ? "En espera" : "Cancelada"}</span>{b.status !== "cancelled" && <button className={secondaryClass} disabled={busy || adminPeople.some((p) => p.bookingId === b.id && ["aboard", "away"].includes(p.movement))} onClick={() => { const reason = window.prompt("Motivo de cancelación"); if (reason) void command("cancelBooking", { bookingId: b.id, reason }, "Cancelar esta reserva?"); }}>Cancelar reserva</button>}</li>)}</ul></section>
    <form className={`${panelClass} space-y-2`} onSubmit={(e) => { e.preventDefault(); void command("addPayment", { bookingId: payment.bookingId, amountMinor: amountToMinor(payment.amount), currency: payment.currency, method: payment.method, reference: payment.reference }).then((saved) => { if (saved) setPayment({ ...payment, amount: "", reference: "" }); }); }}><h3 className="text-lg font-bold">Registrar pago recibido</h3><label className="block">Reserva<select className={inputClass} required value={payment.bookingId} onChange={(e) => setPayment({ ...payment, bookingId: e.target.value })}><option value="">Reserva</option>{trip.bookings.map((b) => <option key={b.id} value={b.id}>{b.reference} · {b.customerName}</option>)}</select></label><label className="block">Monto recibido ({payment.currency})<input className={inputClass} type="text" inputMode="decimal" pattern="[0-9]{1,8}([.,][0-9]{1,2})?" placeholder="Ej. 25,50" required value={payment.amount} onChange={(e) => setPayment({ ...payment, amount: e.target.value })} /></label><div className="grid grid-cols-2 gap-2"><label className="block">Moneda<select className={inputClass} value={payment.currency} onChange={(e) => setPayment({ ...payment, currency: e.target.value })}><option>USD</option><option>VES</option></select></label><label className="block">Método<input className={inputClass} value={payment.method} onChange={(e) => setPayment({ ...payment, method: e.target.value })} /></label></div><label className="block">Referencia del pago (opcional)<input className={inputClass} placeholder="Número o nota" value={payment.reference} onChange={(e) => setPayment({ ...payment, reference: e.target.value })} /></label><button className={buttonClass} disabled={busy}>Guardar recibo manual</button><p className="text-sm text-slate-600">Verifica el pago manualmente antes de registrarlo.</p></form>
    <form className={`${panelClass} space-y-2`} onSubmit={(e) => { e.preventDefault(); void command("addCost", { label: cost.label, amountMinor: amountToMinor(cost.amount), currency: cost.currency }).then((saved) => { if (saved) setCost({ ...cost, label: "", amount: "" }); }); }}><h3 className="text-lg font-bold">Registrar costo</h3><label className="block">Concepto<input className={inputClass} required value={cost.label} onChange={(e) => setCost({ ...cost, label: e.target.value })} /></label><div className="grid grid-cols-2 gap-2"><label className="block">Monto ({cost.currency})<input className={inputClass} type="text" inputMode="decimal" pattern="[0-9]{1,8}([.,][0-9]{1,2})?" placeholder="Ej. 25,50" required value={cost.amount} onChange={(e) => setCost({ ...cost, amount: e.target.value })} /></label><label className="block">Moneda<select className={inputClass} value={cost.currency} onChange={(e) => setCost({ ...cost, currency: e.target.value })}><option>USD</option><option>VES</option></select></label></div><button className={buttonClass} disabled={busy}>Guardar costo</button></form>
    <form className={`${panelClass} space-y-2`} onSubmit={(e) => { e.preventDefault(); void command("addService", { label: service.label, quantity: Number(service.quantity), unitAmountMinor: amountToMinor(service.unitAmount), currency: service.currency }).then((saved) => { if (saved) setService({ ...service, label: "", quantity: "1", unitAmount: "0" }); }); }}><h3 className="text-lg font-bold">Agregar extra o servicio</h3><label className="block">Nombre del servicio<input className={inputClass} required value={service.label} onChange={(e) => setService({ ...service, label: e.target.value })} /></label><div className="grid grid-cols-2 gap-2"><label className="block">Cantidad<input className={inputClass} type="number" min="1" max="130" value={service.quantity} onChange={(e) => setService({ ...service, quantity: e.target.value })} /></label><label className="block">Precio unitario ({service.currency})<input className={inputClass} aria-label="Precio unitario" type="text" inputMode="decimal" pattern="[0-9]{1,8}([.,][0-9]{1,2})?" placeholder="Ej. 5,00" value={service.unitAmount} onChange={(e) => setService({ ...service, unitAmount: e.target.value })} /></label></div><label className="block">Moneda del extra<select className={inputClass} value={service.currency} onChange={(e) => setService({ ...service, currency: e.target.value })}><option>USD</option><option>VES</option></select></label><button className={buttonClass} disabled={busy}>Agregar servicio</button></form>
    <section className={panelClass}><h3 className="text-lg font-bold">Lista de espera</h3>{trip.bookings.filter((b) => b.status === "waitlist").map((b) => <div key={b.id} className="flex items-center justify-between gap-2 border-t py-2"><span>{b.reference} · {b.customerName} ({b.seats})</span><button className={secondaryClass} disabled={busy} onClick={() => void command("promoteBooking", { bookingId: b.id }, "Confirmar promoción a reserva? Se comprobarán los lugares disponibles.")}>Promover</button></div>)}{!trip.bookings.some((b) => b.status === "waitlist") && <p className="text-slate-600">No hay personas en espera.</p>}</section>
    <section className={panelClass}><h3 className="text-lg font-bold">Estado y cierre</h3><div className="flex flex-wrap gap-2">{trip.status === "planned" && <button className={buttonClass} onClick={() => void command("changeTripStatus", { status: "boarding" })}>Abrir abordaje</button>}{trip.status === "boarding" && <div className="w-full space-y-2"><label className="block font-semibold">Cuenta físicamente a las personas a bordo<input className={inputClass} type="number" min="0" max="130" placeholder="Escribe el conteo" value={physicalCount} onChange={(e) => setPhysicalCount(e.target.value)} /></label><label className="flex items-start gap-2"><input className="mt-1 h-6 w-6" type="checkbox" checked={countConfirmed} onChange={(e) => setCountConfirmed(e.target.checked)} />Confirmo que comparé el conteo físico con la lista impresa.</label><button className={buttonClass} disabled={!countConfirmed || physicalCount === "" || Number(physicalCount) !== trip.totals.aboard || busy} onClick={() => void command("changeTripStatus", { status: "underway", physicalCount: Number(physicalCount), paperEntriesResolved: true }, "Iniciar el paseo con el conteo confirmado?")}>Confirmar inicio</button></div>}{trip.status === "underway" && <div className="w-full space-y-2"><label className="block font-semibold">Personas a bordo al finalizar<input className={inputClass} type="number" min="0" max="130" placeholder="Escribe 0 después del conteo" value={physicalCount} onChange={(e) => setPhysicalCount(e.target.value)} /></label><label className="flex items-start gap-2"><input className="mt-1 h-6 w-6" type="checkbox" checked={countConfirmed} onChange={(e) => setCountConfirmed(e.target.checked)} />Confirmo que todas las personas desembarcaron y revisé la lista.</label><button className={buttonClass} disabled={!countConfirmed || physicalCount !== "0" || busy} onClick={() => void command("changeTripStatus", { status: "completed", physicalCount: Number(physicalCount), paperEntriesResolved: true }, "Confirmas que todas las personas desembarcaron y el conteo físico es cero?")}>Finalizar paseo</button></div>}<button className={secondaryClass} onClick={() => void command("exportManifest", {}, "El manifiesto incluye datos personales. ¿Descargarlo en este dispositivo autorizado?")}>Descargar manifiesto</button></div>{trip.reconciliationRequired && <div className="mt-3 space-y-2 rounded bg-amber-100 p-3"><p>Revisión necesaria: {trip.reconciliationNote}</p><ResolveReconciliation revision={trip.revision} busy={busy} command={command} /></div>}</section>
    {["planned", "boarding"].includes(trip.status) && <details className={`${panelClass} border-red-200`}><summary className="cursor-pointer font-semibold text-red-900">Cancelar este paseo</summary><label className="mt-3 block">Motivo de cancelación<input className={inputClass} value={cancellationReason} onChange={(e) => setCancellationReason(e.target.value)} minLength={2} maxLength={1000} /></label><button className={`${secondaryClass} mt-2 border-red-700 text-red-900`} disabled={busy || cancellationReason.trim().length < 2 || trip.totals.aboard > 0 || trip.totals.away > 0} onClick={() => void command("changeTripStatus", { status: "cancelled", reason: cancellationReason.trim() }, "¿Confirmas la cancelación del paseo?")}>Confirmar cancelación</button></details>}
    {trip.report && <section className={panelClass}><h3 className="text-lg font-bold">Resumen por moneda</h3>{trip.report.byCurrency.map((r) => <div key={r.currency} className="mt-2 rounded bg-slate-50 p-3"><strong>{r.currency}</strong><p>Reservas: {formatMoney(r.bookingTotalMinor, r.currency)} · Recibido: {formatMoney(r.receivedMinor, r.currency)} · Pendiente: {formatMoney(r.outstandingMinor, r.currency)}</p><p>Extras: {formatMoney(r.extrasMinor, r.currency)} · Costos: {formatMoney(r.costMinor, r.currency)} · Neto recibido: {formatMoney(r.cashMarginMinor, r.currency)}</p></div>)}<h4 className="mt-3 font-bold">Agencias</h4>{trip.report.agency.map((r) => <p key={r.agency}>{r.agency || "Directo"}: {r.bookings} reservas · {r.seats} pasajeros</p>)}</section>}
    <section className={panelClass}><h3 className="text-lg font-bold">Briefing y borradores</h3><ul className="list-disc space-y-1 pl-5">{(trip.briefing || ["El briefing aparecerá con la información del paseo."]).map((line, i) => <li key={i}>{line}</li>)}</ul>{trip.drafts && Object.entries(trip.drafts).map(([key, draft]) => <details key={key} className="mt-2 rounded border p-3"><summary className="cursor-pointer font-semibold">{key === "preTrip" ? "Antes del paseo" : key === "followUp" ? "Seguimiento" : "Aviso de cancelación"} · borrador</summary><p className="mt-2 whitespace-pre-wrap">{draft}</p><button className={`${secondaryClass} mt-2`} onClick={() => void navigator.clipboard.writeText(draft)}>Copiar borrador</button></details>)}</section>
    {selectedTicket && <TicketModal code={selectedTicket} onClose={() => setSelectedTicket("")} />}
  </div>;
}
function PassengerCorrection({ person, revision, busy, command }: { person: AdminPassenger; revision: number; busy: boolean; command: (action: string, fields?: Record<string, unknown>, confirmation?: string) => Promise<boolean> }) { const [open, setOpen] = useState(false); const [reason, setReason] = useState(""); const [name, setName] = useState(person.name); const [doc, setDoc] = useState(""); const [docType, setDocType] = useState<NonNullable<AdminPassenger["documentType"]>>(person.documentType || "cedula"); const [phone, setPhone] = useState(person.phone); const [email, setEmail] = useState(person.email); const [minor, setMinor] = useState(person.minor); const [rep, setRep] = useState(person.representativeName); if (!open) return <button className={secondaryClass} onClick={() => setOpen(true)}>Corregir datos</button>; return <div className="w-full space-y-2 rounded bg-slate-50 p-3"><p className="font-semibold">Escribe el dato correcto y el motivo.</p><label className="block">Nombre legal<input className={inputClass} value={name} onChange={(e) => setName(e.target.value)} /></label><label className="block">Tipo de documento<select className={inputClass} value={docType} onChange={(e) => setDocType(e.target.value as typeof docType)}><option value="cedula">Cédula</option><option value="passport">Pasaporte</option><option value="other">Otro</option><option value="representative">Representante</option></select></label><label className="block">Número nuevo de documento<input className={inputClass} value={doc} onChange={(e) => setDoc(e.target.value)} autoComplete="off" /></label><label className="block">Teléfono<input className={inputClass} value={phone} onChange={(e) => setPhone(e.target.value)} /></label><label className="block">Correo<input className={inputClass} value={email} onChange={(e) => setEmail(e.target.value)} /></label><label className="flex items-center gap-2"><input type="checkbox" className="h-6 w-6" checked={minor} onChange={(e) => setMinor(e.target.checked)} />Menor de edad</label>{minor && <label className="block">Representante<input className={inputClass} value={rep} onChange={(e) => setRep(e.target.value)} /></label>}<label className="block">Motivo<input className={inputClass} value={reason} onChange={(e) => setReason(e.target.value)} /></label><button className={buttonClass} disabled={busy || reason.length < 2 || doc.length < 3 || name.length < 2} onClick={() => { void command("correctPassenger", { passengerId: person.id, expectedRevision: revision, reason, name, documentType: docType, documentNumber: doc, phone, email, minor, representativeName: rep }, "Guardar la corrección y emitir un boleto nuevo?"); setOpen(false); }}>Guardar corrección</button><button className={secondaryClass} onClick={() => setOpen(false)}>Cancelar</button></div>; }
function MovementCorrection({ person, revision, busy, command }: { person: AdminPassenger; revision: number; busy: boolean; command: (action: string, fields?: Record<string, unknown>, confirmation?: string) => Promise<boolean> }) { const [reason, setReason] = useState(""); const [target, setTarget] = useState(person.movement); return <div className="w-full space-y-2 rounded border border-amber-300 p-3"><strong>Corregir un movimiento</strong><label className="block">Estado correcto<select className={inputClass} value={target} onChange={(e) => setTarget(e.target.value as typeof person.movement)}><option value="awaiting">Por abordar</option><option value="aboard">A bordo</option><option value="away">En parada</option><option value="deboarded">Desembarcó</option></select></label><label className="block">Motivo<input className={inputClass} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Explica el error" /></label><button className={secondaryClass} disabled={busy || reason.length < 2 || target === person.movement} onClick={() => void command("correctMovement", { passengerId: person.id, expectedMovement: person.movement, expectedRevision: revision, newMovement: target, reason }, "¿Confirmas la corrección del movimiento?")}>Guardar corrección</button></div>; }
function IncidentForm({ disabled, command }: { disabled: boolean; command: (action: string, fields?: Record<string, unknown>) => Promise<boolean> }) { const [text, setText] = useState(""); return <form className={`${panelClass} space-y-2`} onSubmit={async (e) => { e.preventDefault(); if (disabled) return; await submitMarineDraft(() => command("addIncident", { text }), () => setText("")); }}><h3 className="font-bold">Anotar una incidencia</h3><label className="block">Nota para el equipo<textarea className={`${inputClass} min-h-24 py-3`} value={text} onChange={(e) => setText(e.target.value)} minLength={2} maxLength={1000} required /></label><button className={secondaryClass} disabled={disabled}>Guardar nota</button></form>; }
function ResolveReconciliation({ revision, busy, command }: { revision: number; busy: boolean; command: (action: string, fields?: Record<string, unknown>, confirmation?: string) => Promise<boolean> }) { const [physicalCount, setPhysicalCount] = useState(""); const [reason, setReason] = useState(""); const [confirmed, setConfirmed] = useState(false); return <div className="space-y-2"><label className="block">Escribe el conteo físico de la lista<input className={inputClass} type="number" min="0" max="130" value={physicalCount} onChange={(e) => setPhysicalCount(e.target.value)} /></label><label className="flex items-start gap-2"><input className="mt-1 h-6 w-6" type="checkbox" checked={confirmed} onChange={(e) => setConfirmed(e.target.checked)} />Confirmo que comparé cada movimiento con la lista maestra.</label><label className="block">Qué se revisó<input className={inputClass} value={reason} onChange={(e) => setReason(e.target.value)} /></label><button className={buttonClass} disabled={busy || physicalCount === "" || reason.length < 2 || !confirmed} onClick={() => void command("resolveReconciliation", { expectedRevision: revision, physicalCount: Number(physicalCount), reason }, "Confirmas que comparaste y resolviste la lista maestra?")}>Confirmar revisión</button></div>; }
function TicketModal({ code, onClose }: { code: string; onClose: () => void }) { const [image, setImage] = useState(""); useEffect(() => { void ticketQrDataUrl(code).then(setImage).catch(() => setImage("")); }, [code]); return <div className="fixed inset-0 z-40 grid place-items-center bg-black/60 p-4"><div className={`${panelClass} marine-print-scope w-full max-w-sm text-center`}><h2 className="text-xl font-bold">Boleto del pasajero</h2><p className="my-3 break-all font-mono text-lg">{code}</p>{image ? <Image unoptimized width={256} height={256} className="mx-auto h-64 w-64" src={image} alt="Código QR del boleto" /> : <p>Preparando código QR…</p>}<p className="text-sm">Muestra este código al abordar. También puedes usar el código escrito.</p><div className="mt-3 flex justify-center gap-2"><button className={buttonClass} onClick={() => window.print()}>Imprimir</button><button className={`${secondaryClass} marine-no-print`} onClick={onClose}>Cerrar</button></div></div></div>; }
function Scanner({ onClose, onCode }: { onClose: () => void; onCode: (value: string) => void }) { const video = useRef<HTMLVideoElement>(null); const onCodeRef = useRef(onCode); const [message, setMessage] = useState("Abre la cámara para escanear. También puedes introducir el código manualmente."); const [manual, setManual] = useState(""); useEffect(() => { onCodeRef.current = onCode; }, [onCode]); useEffect(() => { let controls: { stop: () => void } | null = null; let shouldStop = false; let alive = true; void (async () => { try { const { BrowserMultiFormatReader } = await import("@zxing/browser"); const reader = new BrowserMultiFormatReader(); const started = await reader.decodeFromVideoDevice(undefined, video.current!, (result) => { if (result && alive && !shouldStop) { shouldStop = true; controls?.stop(); onCodeRef.current(result.getText()); } }); controls = started; if (shouldStop || !alive) controls.stop(); } catch { if (alive) setMessage("No pudimos abrir la cámara. Escribe el código del boleto abajo o busca por nombre."); } })(); return () => { alive = false; controls?.stop(); }; }, []); return <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/70 p-4"><div className={`${panelClass} w-full max-w-lg space-y-3`}><h2 className="text-xl font-bold">Escanear boleto</h2><p>{message}</p><video ref={video} className="aspect-video w-full rounded-xl bg-black" muted playsInline /><label className="block font-semibold">Código manual<input className={`${inputClass} mt-1`} value={manual} onChange={(e) => setManual(e.target.value.toUpperCase())} /></label><div className="flex gap-2"><button className={buttonClass} disabled={!manual.trim()} onClick={() => onCode(manual)}>Buscar código</button><button className={`${secondaryClass} marine-no-print`} onClick={onClose}>Cerrar</button></div></div></div>; }

